package errors

import (
	"reflect"
	"testing"
)

func TestFormatFileHeader(t *testing.T) {
	want := []string{
		"// Code generated by protoc-gen-sphere-errors. DO NOT EDIT.",
		"// versions:",
		"// - protoc-gen-sphere-errors v1.2.3",
		"// - protoc                   v5.29.0",
		"// source: errors.proto",
		"",
		"package errorsv1",
		"",
	}
	got := formatFileHeader("v1.2.3", "v5.29.0", "errors.proto", "errorsv1", false)
	if !reflect.DeepEqual(got, want) {
		t.Errorf("formatFileHeader() = %#v, want %#v", got, want)
	}

	unknown := formatFileHeader("", "v5.29.0", "errors.proto", "errorsv1", false)
	if got, want := unknown[2], "// - protoc-gen-sphere-errors (unknown)"; got != want {
		t.Errorf("unset plugin version line = %q, want %q", got, want)
	}

	deprecated := formatFileHeader("v1.2.3", "v5.29.0", "errors.proto", "errorsv1", true)
	if got, want := deprecated[4], "// errors.proto is a deprecated file."; got != want {
		t.Errorf("deprecated source line = %q, want %q", got, want)
	}
}
